    $raw=$r['meta']['statuscode']??null;$ocs=(is_int($raw) || (is_string($raw) && preg_match('/^[0-9]{1,4}$/D',$raw))) && (int)$raw>=0 && (int)$raw<=9999?(int)$raw:0;
